optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/xml.rs b/tools/bot-evaluation/src/xml.rs
index 3accb4ad..df74ac88 100644
--- a/tools/bot-evaluation/src/xml.rs
+++ b/tools/bot-evaluation/src/xml.rs
@@ -163,8 +163,10 @@ fn emit(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
         }
     }
     if value.is_null() {
-        start.push_attribute(("xsi:nil", "true"));
-        writer.write_event(Event::Empty(start))?;
+        let bytes = writer.get_mut();
+        bytes.push(b'<');
+        bytes.extend_from_slice(name.as_bytes());
+        bytes.extend_from_slice(b" xsi:nil=\"true\"/>");
         return Ok(());
     }
     writer.write_event(Event::Start(start))?;
